import{_ as t,o as a,c as n,ae as i}from"./chunks/framework.BONZgKEB.js";const u=JSON.parse('{"title":"Event Management","description":"","frontmatter":{},"headers":[],"relativePath":"guide/event-management.md","filePath":"guide/event-management.md"}'),o={name:"guide/event-management.md"};function r(s,e,l,h,c,d){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="event-management" tabindex="-1">Event Management <a class="header-anchor" href="#event-management" aria-label="Permalink to &quot;Event Management&quot;">​</a></h1><p>This guide covers the initial creation and configuration of an archery event using the <strong>Archery Event Management</strong> application.</p><h2 id="_1-creating-a-new-event" tabindex="-1">1. Creating a New Event <a class="header-anchor" href="#_1-creating-a-new-event" aria-label="Permalink to &quot;1. Creating a New Event&quot;">​</a></h2><p>To host a new event, you must first create it through the application dashboard.</p><ol><li>Navigate to the <strong>Events</strong> section in the main navigation bar.</li><li>Click the <strong>Create Event</strong> button.</li><li>Fill in the required details: <ul><li><strong>Event Name:</strong> A clear, identifiable name for your competition.</li><li><strong>Dates:</strong> Select the start and end dates.</li><li><strong>Location:</strong> The venue where the event will take place.</li><li><strong>Ruleset:</strong> Define the governing rules (e.g., WA - World Archery).</li></ul></li><li>Click <strong>Submit</strong> to create the event.</li></ol><p>Once created, you will be redirected to the <strong>Event Dashboard</strong>, also known as the <strong>Host Panel</strong>.</p><h2 id="_2-the-host-panel" tabindex="-1">2. The Host Panel <a class="header-anchor" href="#_2-the-host-panel" aria-label="Permalink to &quot;2. The Host Panel&quot;">​</a></h2><p>The Host Panel (<code>EventDetailView</code>) is your central control room for managing the event lifecycle. It provides several tabs to manage different aspects of your event:</p><h3 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h3><p>This tab displays high-level information about the event, including its status, dates, and total number of participants.</p><h3 id="athletes" tabindex="-1">Athletes <a class="header-anchor" href="#athletes" aria-label="Permalink to &quot;Athletes&quot;">​</a></h3><p>Before a competition can begin, athletes must be registered to the event.</p><ul><li>Use the <strong>Register Athlete</strong> action to add participants.</li><li>You can view the list of all registered athletes, their associated teams, and their respective categories (e.g., Recurve Men, Compound Women).</li></ul><h3 id="referees" tabindex="-1">Referees <a class="header-anchor" href="#referees" aria-label="Permalink to &quot;Referees&quot;">​</a></h3><p>Referees are responsible for verifying scores during the event.</p><ul><li>Assign users with the referee role to your event.</li><li>Only registered referees will have access to the scoring sheets during the competition.</li></ul><h3 id="host-settings" tabindex="-1">Host Settings <a class="header-anchor" href="#host-settings" aria-label="Permalink to &quot;Host Settings&quot;">​</a></h3><p>This tab provides administrative controls:</p><ul><li><strong>Edit Details:</strong> Modify the event name, dates, or location.</li><li><strong>Generate Competitions:</strong> Based on the registered athletes, the system can automatically group them into valid competition categories.</li></ul><h2 id="_3-advancing-to-competition-setup" tabindex="-1">3. Advancing to Competition Setup <a class="header-anchor" href="#_3-advancing-to-competition-setup" aria-label="Permalink to &quot;3. Advancing to Competition Setup&quot;">​</a></h2><p>Once all your athletes and referees are registered, and your event details are finalized, you are ready to transition to the <strong>Competition Setup</strong> phase. This involves scheduling the Qualification rounds and generating Elimination brackets.</p><p>👉 <em>Next Step:</em> <a href="./competition-setup.html">Learn how to set up your competitions</a></p>',22)])])}const p=t(o,[["render",r]]);export{u as __pageData,p as default};
